style.css:
/* ======================================================
   CHATGPT – CYBER SUNSET GLASS UI (FULLY UNIFIED)
   Glassmorphism • Gradient Accent • Soft Neumorphism
====================================================== */

/* ================================
   VARIABLES
================================ */
:root {
  --accent-gradient: linear-gradient(135deg, #ff5f6d, #7c7cff);

  --bg-base: rgba(10, 12, 18, 0.88);
  --glass-bg: rgba(255, 255, 255, 0.07);
  --glass-border: rgba(255, 255, 255, 0.18);

  --text-primary: #eceef3;
  --text-secondary: #a6acc0;

  --blur: 22px;
  --radius: 20px;
  --radius-small: 14px;

  --shadow-glass:
    0 10px 35px rgba(0, 0, 0, 0.45);

  --shadow-inset:
    inset 6px 6px 14px rgba(0, 0, 0, 0.45),
    inset -6px -6px 14px rgba(255, 255, 255, 0.05);
}

/* ================================
   APP BACKGROUND
================================ */
html,
body {
  background:
    radial-gradient(circle at top left, rgba(255,95,109,0.18), transparent 45%),
    radial-gradient(circle at bottom right, rgba(124,124,255,0.22), transparent 45%),
    #0a0c12 !important;
  color: var(--text-primary) !important;
}

/* ================================
   GLOBAL GLASS BASE
================================ */
main,
aside,
div[data-message-author-role],
form,
form textarea {
  background: var(--glass-bg) !important;
  backdrop-filter: blur(var(--blur));
  -webkit-backdrop-filter: blur(var(--blur));
  border: 1px solid var(--glass-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-glass);
}

/* ================================
   SIDEBAR (YOUR CHATS)
================================ */
aside {
  margin: 12px;
  padding: 12px;
}

/* "Your chats" header */
aside h2,
aside h3,
aside header {
  background: rgba(255,255,255,0.06) !important;
  backdrop-filter: blur(var(--blur));
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-small);
  padding: 10px 14px;
  margin-bottom: 10px;
  box-shadow: var(--shadow-glass);
}

/* Chat list items */
aside nav a {
  margin: 6px 4px;
  padding: 10px 14px;
  border-radius: var(--radius-small);
  background: rgba(255,255,255,0.04);
  transition: all 0.3s ease;
}

/* Hover */
aside nav a:hover {
  background: rgba(255,255,255,0.08);
  transform: translateX(2px);
}

/* Active chat */
aside nav a[aria-current="page"] {
  background:
    linear-gradient(
      135deg,
      rgba(255,255,255,0.18),
      rgba(255,255,255,0.05)
    );
  border-left: 4px solid transparent;
  border-image: var(--accent-gradient) 1;
}

/* ================================
   CHAT MESSAGES
================================ */
div[data-message-author-role] {
  margin: 16px 0 !important;
  padding: 20px 22px !important;
}

/* Assistant */
div[data-message-author-role="assistant"] {
  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,0.08),
      rgba(255,255,255,0.03)
    ) !important;
}

/* User */
div[data-message-author-role="user"] {
  box-shadow: var(--shadow-inset);
  position: relative;
}

/* User gradient stripe */
div[data-message-author-role="user"]::before {
  content: "";
  position: absolute;
  left: 0;
  top: 14px;
  bottom: 14px;
  width: 4px;
  background: var(--accent-gradient);
  border-radius: 4px;
}

/* ================================
   PROMPT BOX (FULL CONTAINER)
================================ */
form {
  padding: 12px !important;
  margin-top: 12px;
}

/* Textarea */
form textarea {
  border-radius: 28px !important;
  box-shadow: var(--shadow-inset);
  padding: 18px !important;
  color: var(--text-primary) !important;
  background: rgba(255,255,255,0.06) !important;
}

/* Focus state */
form textarea:focus {
  border-color: transparent !important;
  border-image: var(--accent-gradient) 1;
  box-shadow:
    0 0 0 2px rgba(255,255,255,0.15),
    var(--shadow-inset);
}

/* Send button */
button[type="submit"] {
  background: var(--accent-gradient) !important;
  border-radius: 50% !important;
  box-shadow: var(--shadow-glass);
}

/* ================================
   TEXT & CODE
================================ */
p,
li,
span {
  color: var(--text-primary) !important;
  line-height: 1.6;
}

code,
pre {
  background: rgba(0,0,0,0.45) !important;
  border-radius: var(--radius-small);
}

/* ================================
   INTERACTION POLISH
================================ */
a,
button {
  transition: all 0.25s ease;
}

button:hover {
  transform: translateY(-1px);
}

/* ================================
   SCROLLBAR – GRADIENT
================================ */
*::-webkit-scrollbar {
  width: 8px;
}

*::-webkit-scrollbar-thumb {
  background: var(--accent-gradient);
  border-radius: 20px;
}
